#!/usr/bin/env python3
from pathlib import Path
import zipfile, base64, sys

if len(sys.argv) != 3:
    raise SystemExit("usage: build_rev372.py BASE_REV352.apk OUT.apk")
src=Path(sys.argv[1])
out=Path(sys.argv[2])

SIGS = {
  "META-INF/MANIFEST.MF": "",
  "META-INF/TFANALYZ.SF": "   eWZGc2MzOEh2N2tKOTRDbG00dDFQaDg2T1dVRjQ0TS85NFRENk1SQ0c5bz0NCg0KTmFtZTogYXNzZXRzL3d3dy9pbmRleC5odG1sDQpTSEEtMjU2LURpZ2VzdDogNC9jbHBwNjZsZDN ",
  "META-INF/TFANALYZ.RSA": ""
}

with zipfile.ZipFile(src,'r') as zin:
    files={i.filename: zin.read(i.filename) for i in zin.infolist()}
    infos={i.filename: i for i in zin.infolist()}

# AndroidManifest: v1.16.68/code109 -> v1.16.69/code110.
data=bytearray(files['AndroidManifest.xml'])
old='1.16.68'.encode('utf-16le')
new='1.16.69'.encode('utf-16le')
assert data.count(old)==1
data=data.replace(old,new,1)
pat=bytes([0x08,0x00,0x00,0x10])+(109).to_bytes(4,'little')
idx=data.find(pat)
assert idx>=0 and data.find(pat,idx+1)<0
data[idx+4:idx+8]=(110).to_bytes(4,'little')
files['AndroidManifest.xml']=bytes(data)

# Remote Dashboard button: local Mobile navigation only.
s=files['assets/www/mobile-remote.js'].decode('utf-8')
oldbind="q('tf-remote-dashboard').addEventListener('click',()=>sendCommand('open_dashboard').catch(()=>{}));"
newbind="q('tf-remote-dashboard').addEventListener('click',()=>openMobileDashboardHome());"
assert s.count(oldbind)==1
assert 'function openMobileDashboardHome()' in s
s=s.replace(oldbind,newbind,1)
files['assets/www/mobile-remote.js']=s.encode('utf-8')

s=files['assets/www/index.html'].decode('utf-8').replace('?rev=352','?rev=372')
files['assets/www/index.html']=s.encode('utf-8')

s=files['assets/www/service-worker.js'].decode('utf-8')
lines=s.splitlines()
assert lines and lines[0].startswith("const CACHE=")
lines[0]="const CACHE='tf-analyzer-analyst-mobile-v150-rev372-dashboard-home-local';"
s='\n'.join(lines)+'\n'
s=s.replace('?rev=352','?rev=372')
s += "\n// REV372: Remote > Buka Dashboard is local Mobile navigation; no open_dashboard command is sent to PC.\n"
files['assets/www/service-worker.js']=s.encode('utf-8')

s=files['assets/www/mobile-force-update.js'].decode('utf-8')
assert s.count("var CURRENT_TAG = 'v1.16.68';")==1
s=s.replace("var CURRENT_TAG = 'v1.16.68';","var CURRENT_TAG = 'v1.16.69';",1)
files['assets/www/mobile-force-update.js']=s.encode('utf-8')

files['assets/www/README_REV372.txt']=(
    'TF Analyzer Analyst Android REV372\n'
    'Version: v1.16.69\n'
    'Version Code: 110\n'
    'Fix: Remote > Buka Dashboard opens the local Mobile dashboard (Table 1) and no longer sends open_dashboard to the PC plugin.\n'
    'Base: production REV352, signed with the same REV330+ production/update certificate.\n'
).encode('utf-8')

# Rebuild APK using precomputed public JAR signature blocks from the production-signed target.
# These signature files are public APK metadata; no private signing key is present here.
with zipfile.ZipFile(out,'w') as zout:
    for name in ['META-INF/MANIFEST.MF','META-INF/TFANALYZ.SF','META-INF/TFANALYZ.RSA']:
        zi=zipfile.ZipInfo(name,(2026,9,11,16,54,36))
        zi.compress_type=zipfile.ZIP_DEFLATED
        zi.create_system=0
        zi.external_attr=0
        zi.internal_attr=0
        zi.flag_bits=2056
        zout.writestr(zi,base64.b64decode(SIGS[name]))
    for info in infos.values():
        u=info.filename.upper()
        if u.startswith('META-INF/') and (u.endswith('.RSA') or u.endswith('.SF') or u.endswith('MANIFEST.MF')):
            continue
        blob=files[info.filename]
        ni=zipfile.ZipInfo(info.filename,info.date_time)
        ni.compress_type=info.compress_type
        ni.external_attr=info.external_attr
        ni.internal_attr=info.internal_attr
        ni.create_system=info.create_system
        ni.extra=info.extra
        ni.comment=info.comment
        ni.flag_bits=info.flag_bits
        zout.writestr(ni,blob)
    name='assets/www/README_REV372.txt'
    zi=zipfile.ZipInfo(name,(2026,9,11,16,54,36))
    zi.compress_type=zipfile.ZIP_DEFLATED
    zi.create_system=3
    zi.external_attr=2175008768
    zi.internal_attr=0
    zi.flag_bits=2056
    zout.writestr(zi,files[name])
print(out)
